package dev.astralreach.hytale;
import com.hypixel.hytale.component.*;import com.hypixel.hytale.protocol.packets.interface_.*;import com.hypixel.hytale.server.core.entity.entities.Player;import com.hypixel.hytale.server.core.entity.entities.player.pages.InteractiveCustomUIPage;import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;import com.hypixel.hytale.server.core.modules.time.WorldTimeResource;import com.hypixel.hytale.server.core.ui.builder.*;import com.hypixel.hytale.server.core.universe.PlayerRef;import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;import dev.astralreach.core.StationPass;import java.util.*;
final class StationTrackerPage extends InteractiveCustomUIPage<StationPage.Action>{
 private String filter="Own";private int page;private UUID selected;private List<StationSkyCatalog.Entry>rows=List.of();private long at;
 StationTrackerPage(PlayerRef p){super(p,CustomPageLifetime.CanDismiss,StationPage.Action.CODEC);selected=p.getUuid();}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){if(!StationFlyovers.surface(s.getExternalData().getWorld())){AstralReachPlugin.message(p,"Use the tracker on Orbis to predict local sky passes.");return;}Observatory.end(s,r,p);StationSkyCatalog.refresh();s.getComponent(r,Player.getComponentType()).getPageManager().openCustomPage(r,s,new StationTrackerPage(p));}
 private void labels(Store<EntityStore>s,Ref<EntityStore>r,UICommandBuilder c){rows=StationSkyCatalog.entries().stream().filter(e->filter.equals("All")||filter.equals("Own")&&e.owner().equals(playerRef.getUuid())||filter.equals("Invited")&&e.crew().contains(playerRef.getUuid())).toList();page=Math.clamp(page,0,Math.max(0,(rows.size()-1)/5));var chosen=rows.stream().filter(e->e.owner().equals(selected)).findFirst().orElse(rows.isEmpty()?null:rows.getFirst());if(chosen!=null)selected=chosen.owner();
  for(int i=0;i<5;i++){int index=page*5+i;c.set("#Row"+i+".Visible",index<rows.size());if(index<rows.size()){var e=rows.get(index);c.set("#Name"+i+".Text",(e.owner().equals(selected)?"› ":"")+e.name());c.set("#Owner"+i+".Text",e.ownerName());}}
  for(String tab:List.of("Own","Invited","All"))c.set("#"+tab+"Selected.Visible",tab.equals(filter));
  c.set("#Page.Text",(page+1)+" / "+Math.max(1,(rows.size()+4)/5));c.set("#Previous.Disabled",page==0);c.set("#Next.Disabled",(page+1)*5>=rows.size());c.set("#Selected.Text",chosen==null?"No stations":chosen.name());c.set("#SelectedOwner.Text",chosen==null?"Deploy a Station Core from orbit":chosen.ownerName());
  if(chosen==null){c.set("#Countdown.Text","--:--");c.set("#PassState.Text","No matching stations deployed");c.set("#Bearing.Text","");c.set("#Elevation.Text","");c.set("#BearingMarker.Visible",false);for(int i=0;i<40;i++)c.set("#Trace"+i+".Visible",false);return;}
  var t=s.getComponent(r,TransformComponent.getComponentType()).getPosition();var time=s.getResource(WorldTimeResource.getResourceType());double hour=time.getDayProgress()*24;boolean paused=s.getExternalData().getWorld().getWorldConfig().isGameTimePaused();var prediction=StationPass.next(selected,System.currentTimeMillis()/1000d,t.x,t.z,hour,paused?0:WorldTimeResource.getSecondsPerTick(s.getExternalData().getWorld())/3600);c.set("#Countdown.Text",prediction.visible()?"VISIBLE":prediction.waitSeconds()<0?"--:--":NativeUi.duration(prediction.waitSeconds()));c.set("#PassState.Text",prediction.waitSeconds()<0?"No visible pass in the next hour":prediction.visible()?"Sunlit pass visible now":"Until next sunlit pass");c.set("#Bearing.Text",prediction.waitSeconds()<0?"":StationPass.compass(prediction.bearing())+" · "+Math.round(prediction.bearing())+"°");c.set("#Elevation.Text",prediction.waitSeconds()<0?"":Math.round(prediction.maxElevation())+"° maximum elevation");c.set("#BearingMarker.Visible",prediction.waitSeconds()>=0);double seconds=System.currentTimeMillis()/1000d,speed=paused?0:WorldTimeResource.getSecondsPerTick(s.getExternalData().getWorld())/3600;
  for(int i=0;i<40;i++){boolean show=prediction.waitSeconds()>=0;c.set("#Trace"+i+".Visible",show);if(show){double future=prediction.riseSeconds()+(prediction.setSeconds()-prediction.riseSeconds())*i/39d;var dot=StationPass.sample(selected,seconds+future,t.x,t.z,hour+future*speed);position(c,"#Trace"+i,34+(int)(i/39d*420),350-(int)(Math.clamp(Math.toDegrees(dot.elevation()),0,90)/90*118),4,4);}}
  double progress=prediction.visible()?Math.clamp(-prediction.riseSeconds()/(prediction.setSeconds()-prediction.riseSeconds()),0,1):0;double elevation=StationPass.sample(selected,seconds+Math.max(0,prediction.riseSeconds()),t.x,t.z,hour+Math.max(0,prediction.riseSeconds())*speed).elevation();position(c,"#BearingMarker",30+(int)(progress*420),346-(int)(Math.clamp(Math.toDegrees(elevation),0,90)/90*118),12,12);
 }
 private static void position(UICommandBuilder c,String id,int left,int top,int width,int height){var a=new com.hypixel.hytale.server.core.ui.Anchor();a.setLeft(com.hypixel.hytale.server.core.ui.Value.of(left));a.setTop(com.hypixel.hytale.server.core.ui.Value.of(top));a.setWidth(com.hypixel.hytale.server.core.ui.Value.of(width));a.setHeight(com.hypixel.hytale.server.core.ui.Value.of(height));c.setObject(id+".Anchor",a);}
 @Override public void build(Ref<EntityStore>r,UICommandBuilder c,UIEventBuilder e,Store<EntityStore>s){c.append("Pages/AstralReach/StationTracker.ui");labels(s,r,c);for(String a:List.of("Own","Invited","All","Previous","Next","Close"))e.addEventBinding(CustomUIEventBindingType.Activating,"#"+a,EventData.of("Action",a),false);for(int i=0;i<5;i++)e.addEventBinding(CustomUIEventBindingType.Activating,"#Row"+i,EventData.of("Action","Row"+i),false);NativeUi.cue(s,playerRef);}
 void refresh(Store<EntityStore>s,Ref<EntityStore>r){if(System.nanoTime()-at<1_000_000_000L)return;at=System.nanoTime();if(!StationFlyovers.surface(s.getExternalData().getWorld())){close();return;}var c=new UICommandBuilder();labels(s,r,c);sendUpdate(c,false);}
 @Override public void handleDataEvent(Ref<EntityStore>r,Store<EntityStore>s,StationPage.Action a){s.getExternalData().getWorld().execute(()->{if(!r.isValid()||r.getStore()!=s||s.getComponent(r,Player.getComponentType()).getPageManager().getCustomPage()!=this)return;if(a.action.equals("Close")){close();return;}if(List.of("Own","Invited","All").contains(a.action)){filter=a.action;page=0;}else if(a.action.equals("Next"))page++;else if(a.action.equals("Previous"))page--;else if(a.action.matches("Row[0-4]")){int i=page*5+Integer.parseInt(a.action.substring(3));if(i<rows.size())selected=rows.get(i).owner();}var c=new UICommandBuilder();labels(s,r,c);sendUpdate(c,false);});}
}
